var Alloy = require('alloy');

function extractReportsFromResponse (response) 
{
    if (!_.isArray(response) || !_.isArray(response[0])) {
        return [];
    } 

    return response[0];
}

function extractDashboardsFromResponse (response) 
{
    if (!_.isArray(response) || !_.isArray(response[1])) {
        return [];
    } 

    return response[1];
}

