function doesNotContainWhitespace (url) {
    return -1 == ('' + url).indexOf(' ');
}

function removeTokenAuthFromUrl(url) {
    return url.replace(/([?&])token_auth=[^&]*&?/, (match, p1) => p1 === '?' ? '?' : '&')
}

